238	// --- the forced wake (DESIGN §8) ----------------------------------------------
239	
240	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
241	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
242	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
243	// the member wakes its own items with its own token. The enforcer therefore needs
244	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
245	// the enforcer dispatches and the member executes.
246	//
247	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
248	// tasks, so a caller spanning many members never has to know any one member's pack
249	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
250	// report counts only what it woke reads as coverage it did not have.
251	//
252	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
253	// alone and reported as `already`, never re-woken — an episode boundary dropped on
254	// a live claim is exactly the livelock F18 describes.
255	//
256	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (§8's other lever). A
257	// task that completes closes its item, and the next one appears only at the next
258	// anchor — so between the two there is nothing to wake, and that gap is the common
259	// case rather than an edge: a daily task is missing its item for most of the day.
260	// A force that reported "nothing to wake" there would fail on most members most of
261	// the time, which is precisely what a fleet-wide converge lever must not do. The
262	// minted item is an ordinary standing item — same title, no qualifier: it consumes
263	// the CURRENT occurrence, so the scheduler run does not then create a second one beside it,
264	// and it leaves the next anchor's occurrence untouched.
265	export function planWake(spec, tasks = [], items = []) {
266	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
267	  const wake = []; const create = []; const already = []; const unmatched = [];
268	  for (const id of ids) {
269	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
270	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
271	    if (owners.length !== 1) {
272	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
273	      continue;
274	    }
275	    const owner = owners[0];
276	    const { pack, id: task } = owner;
277	    const item = items.find((i) => {
278	      if (i.state !== 'open') return false;
279	      const parsed = parseWorkItemTitle(i.title);
280	      return parsed && parsed.pack === pack && parsed.task === task;
281	    });
282	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
283	    if (IN_FLIGHT.some((l) => hasLabel(item, l))) { already.push({ id, issue: item.number }); continue; }
284	    wake.push({ id: `${pack}/${task}`, issue: item.number });
285	  }
286	  return { wake, create, already, unmatched };
287	}
