289	// The Context a forced standing item carries. It says the force is the only reason
290	// the item exists, because the executor still evaluates the precondition at pick:
291	// a force that finds no work must roll with its reason on record, not invent work.
292	export const FORCED_WAKE_CONTEXT =
293	  'Minted by a force — this task had no open standing item at the time. The precondition is still evaluated at pick, so converge to a no-op if there is nothing to do.';
294	
295	// The states that mean someone already holds this item. `task:agent` counts: the
296	// work is with a session, and waking would hand a second executor the same item.
297	const IN_FLIGHT = [READY, EXECUTING, AGENT];
298	
299	// --- CLI: the thin I/O shell the vendored scheduler run workflow invokes ---------------
300	// Reads the work-item list, plans, applies. All GitHub access is the Action's
301	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
302	// said it is out of the recurring work should not pay for the list that proves it.
303	
304	// Every `[claudinite-work]` issue, state=all, via the ISSUES list API — never the
305	// search index (S6/F11: search is eventually consistent, and a family list that
306	// misses a just-created item mints a duplicate standing item). Bounded by the
307	// scheduled families' need for closed history: closed items are only interesting
308	// back to the widest period, so the listing stops once it is past that.
309	export async function listWorkItems(gh, repo, { since = null } = {}) {
310	  const out = [];
311	  for (let page = 1; ; page += 1) {
312	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
313	      + (since ? `&since=${encodeURIComponent(since)}` : '');
314	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
315	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
316	    for (const i of json) {
317	      if (i.pull_request) continue;
318	      if (!(i.title ?? '').startsWith(WORK_PREFIX)) continue;
319	      out.push({
320	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
321	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
322	        updated_at: i.updated_at,
323	      });
324	    }
325	    if (json.length < 100) break;
326	  }
327	  return out;
328	}
329	
330	// Every OPEN issue carrying the request mark, via the ISSUES list API filtered by
331	// label — never the search index, for the same reason the work-item list is not
332	// (S6/F11): a mark this list misses is a request that silently waits an hour, and a
333	// mark it misses TWICE is one nobody notices was never picked up.
334	export async function listMarkedIssues(gh, repo) {
335	  const out = [];
336	  for (let page = 1; ; page += 1) {
337	    const q = `state=open&labels=${encodeURIComponent(REQUEST_LABEL)}&per_page=100&page=${page}`;
338	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
339	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
340	    for (const i of json) {
341	      if (i.pull_request) continue;
342	      // A work item wearing the mark is not a request: the two vocabularies are
343	      // disjoint on purpose, and adopting one would file a run to implement a run.
344	      if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
345	      // The body comes with the list: a request states what it waits on in it
346	      // (§16.11), and adoption reads that without a second call per marked issue.
347	      out.push({ number: i.number, title: i.title, body: i.body ?? '', state: i.state, labels: labelNames(i) });
348	    }
349	    if (json.length < 100) break;
350	  }
351	  return out;
352	}
