354	async function main() {
355	  // THE OPERATOR HOLD, FIRST ACT (§15.24) — before the config load, before the
356	  // first API call, so a held queue reads nothing and writes nothing rather than
357	  // deriving the world and then declining to act on it.
358	  if (isSuspended()) { console.log('## Claudinite scheduler run\n'); console.log(suspendedNotice()); return; }
359	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
360	  const { discoverTasks } = await import('../discover.mjs');
361	  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
362	  const { ensureLabels, addLabel, removeLabel, comment, closeIssue, createIssue, listComments } = await import('../github.mjs');
363	
364	  const root = process.cwd();
365	  const { repo } = actionRepoContext();
366	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
367	  const config = loadConfig(root);
368	
369	  console.log('## Claudinite scheduler run\n');
370	  if (isDormant(config)) {
371	    console.log('- this project declares itself dormant — no items instantiated, readied or reclaimed');
372	    return;
373	  }
374	
375	  const gh = makeGh();
376	  const { tasks, errors } = await discoverTasks(root, config);
377	  for (const e of errors) console.log(`! ${e.what}`);
378	
379	  const now = new Date();
380	  // Closed items matter only back to the widest occurrence guard (a monthly
381	  // task's period); older history can never change a verdict.
382	  const since = new Date(now.getTime() - 40 * 86400e3).toISOString();
383	  const items = await listWorkItems(gh, repo, { since });
384	  const requests = await listMarkedIssues(gh, repo);
385	
386	  // A `Blocked-by` target need not be a work item — a fan-in blocks on whatever
387	  // its children are — so states come from the fetched items first and a direct
388	  // read otherwise.
389	  const known = new Map(items.map((i) => [i.number, i.state]));
390	  const wanted = new Set();
391	  for (const i of items) {
392	    if (i.state !== 'open' || !i.labels.includes(BLOCKED)) continue;
393	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
394	  }
395	  // A marked issue's own blockers, for the same reason: adoption decides whether the
396	  // item it births is born blocked or ready, and an unread state is never `closed`,
397	  // so a missing read delays the request rather than releasing it (§16.11).
398	  for (const r of requests) {
399	    for (const n of parseBlockedBy(r.body)) if (!known.has(n)) wanted.add(n);
400	  }
401	  for (const n of wanted) {
402	    const { status, json } = await gh(`/repos/${repo}/issues/${n}`);
403	    known.set(n, status === 200 ? json?.state ?? null : null);
404	  }
405	
406	  // One comment read per EXECUTING item — never per item in the repo — so the
407	  // reclaim can measure the holder's own silence rather than the issue's.
408	  for (const item of items) {
409	    if (item.state !== 'open' || !item.labels.includes(EXECUTING)) continue;
410	    item.livenessAt = lastLivenessAt(await listComments(gh, repo, item.number));
411	  }
412	
413	  const { ops } = planSchedulerRun({
414	    tasks, items, requests, now, schedule: config.taskScheduler, stateOf: (n) => known.get(n) ?? null,
415	  });
416	
417	  if (ops.some((o) => o.kind === 'create' || o.kind === 'adopt')) await ensureLabels(gh, repo, QUEUE_LABELS);
418	  // The request labels are ensured whenever the mode can run here at all, not only
419	  // when something was marked: `claude-task` is the entry point, and a label that
420	  // does not exist is one nobody can find in the issue's label picker.
421	  if (tasks.some((t) => `${t.pack}/${t.id}` === REQUEST_TASK_ID)) await ensureLabels(gh, repo, REQUEST_LABELS);
422	
423	  for (const op of ops) {
424	    if (op.kind === 'create') {
425	      const res = await createIssue(gh, repo, { title: op.title, body: op.body, labels: op.labels });
426	      if (res.number) console.log(`- created #${res.number} ${op.pack}/${op.task} [${op.labels.join(' ')}]`);
427	      else console.log(`! could not create the work item for ${op.pack}/${op.task}: ${res.status}`);
428	    } else if (op.kind === 'ready') {
429	      await removeLabel(gh, repo, op.issue, BLOCKED);
430	      await addLabel(gh, repo, op.issue, READY);
431	      console.log(`- readied #${op.issue}`);
432	    } else if (op.kind === 'reclaim') {
433	      // The reclaim comment is also the EPISODE BOUNDARY: every claim before it is
434	      // dead, and arbitrating over dead claims makes one outrank every future live
435	      // claimant — the item then livelocks through reclaim cycles forever (F18).
436	      await comment(gh, repo, op.issue, `${EPISODE_MARKER}\n${op.reason}`);
437	      await removeLabel(gh, repo, op.issue, EXECUTING);
438	      await addLabel(gh, repo, op.issue, op.to);
439	      if (op.triage) await addLabel(gh, repo, op.issue, op.triage);
440	      console.log(`- reclaimed #${op.issue} -> ${op.to}`);
441	    } else if (op.kind === 'adopt') {
442	      const res = await createIssue(gh, repo, { title: op.title, body: op.body, labels: op.labels });
443	      if (!res.number) {
444	        // The mark is NOT consumed when the item could not be created: the request
445	        // has to survive a refused write, and an unconsumed mark is simply adopted
446	        // by the next scheduler run.
447	        console.log(`! could not adopt #${op.request}: the work item was not created (${res.status})`);
