454	      await addLabel(gh, repo, op.request, QUEUED_LABEL);
455	      for (const l of op.consume) await removeLabel(gh, repo, op.request, l);
456	      await comment(gh, repo, op.request,
457	        `Queued as #${res.number}, to run at the \`${op.model}\` family.\n\n`
458	        + (op.blockedBy.length
459	          ? `That item is **blocked** on ${op.blockedBy.map((n) => `#${n}`).join(', ')} — it enters the queue once they close.\n\n`
