1	// The executor (tasks-dispatch DESIGN §6) — a pull worker over the queue. Each
2	// iteration: pick the next ready item, claim it by a verified lease, evaluate the
3	// precondition (THE only place it is ever evaluated), then on a go run code-work and
4	// either converge (agentless) or hand off to an agent session; on a no-go roll a
5	// scheduled item to its next anchor with the reason on record.
6	//
7	// An executor's whole interface is issue read/write plus the repo at HEAD, which
8	// is what makes it platform-agnostic: the reference deployment is a job in the
9	// vendored workflows (the scheduler run's post-scheduler run drain, and a `labeled`-event run for
10	// latency), but a runner anywhere with an issues-scope token qualifies. Nothing
11	// enumerates executors; identity is self-declared in the claim comment.
12	//
13	// The pure decisions live at the top and test with fixtures; the shell below is
14	// the GitHub/code-work/invocation I/O around them.
15	
16	import { pathToFileURL } from 'node:url';
17	import { isSuspended, suspendedNotice } from './suspend.mjs';
18	import { nextAnchor } from './anchors.mjs';
19	import { readyDependents } from './readiness.mjs';
20	import { HEARTBEAT_MS, heartbeatComment, withHeartbeat } from './heartbeat.mjs';
21	import { renderTaskExec } from '../run-record.mjs';
22	import {
23	  READY, URGENT, EXECUTING, AGENT, BLOCKED, NEEDS_HUMAN,
24	  TASK_DONE, TASK_OBSOLETE, QUEUE_LABELS, REQUEST_LABELS, QUEUED_LABEL, isStandingItem,
25	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_FAILURE, triageLabelFor,
26	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
27	  parseWorkItemTitle, parseWorkItemBody, parseContextLines, mergeContext, withNotBefore, withSection, hasLabel, DELIVERED_HEADING, LEGACY_DELIVERED_HEADINGS,
28	  LAST_VERDICT_HEADING, lastVerdictLines } from './work-item.mjs';
