36	// The pick order (DESIGN §6.1): urgent first, then RANDOM among the ready, with
37	// two skip rules read live at pick time. Random rather than oldest-first because
38	// nothing leans on FIFO aging — the stale-ready escalation is period-scale — while
39	// a deterministic order lets one unlucky head dominate every run of a chain
40	// (DESIGN §15.20).
41	//
42	//  - SAME-TITLE MUTEX (S15/F6): skip an item whose exact title has another open
43	//    item executing or handed to an agent — one task, one execution at a time,
44	//    while a fan-out's distinct qualifiers still parallelize.
45	//  - THE `after` YIELD (S24): skip a scheduled item whose task declares `after:
46	//    [T]` while T's standing item is live THIS CYCLE (ready / executing / agent).
47	//    A rolled upstream (blocked until its next anchor: it declined this cycle)
48	//    does not block, and neither does one sitting `needs-human` — a broken
49	//    upstream must not halt its dependents indefinitely. Deliberately NOT a
50	//    `Blocked-by` edge: a standing item that rolls never closes, so blocked-by
51	//    would starve every dependent of a quiet upstream forever.
52	//
53	// `open` is every open work item; `taskAfter(id)` gives a task's declared
54	// upstreams as `<pack>/<task>` ids, and `frequencyOf(id)` that task's declared
55	// frequency at HEAD — which is half of what says whether an item is a standing
56	// occurrence or an ad-hoc run (§15.26). `random` is the tie-break draw, injected
57	// so a test can pin an order the production call deliberately does not have.
58	export function pickOrder(open = [], { taskAfter = () => [], frequencyOf = () => null, random = Math.random } = {}) {
59	  const live = (item) => hasLabel(item, READY) || hasLabel(item, EXECUTING) || hasLabel(item, AGENT);
60	  const standing = (item) => isStandingItem(item, frequencyOf(taskIdOf(item)));
61	  const liveUpstream = (upstreamId) => open.some((o) =>
62	    taskIdOf(o) === upstreamId && standing(o) && live(o));
63	  // One draw per item, taken once: a comparator that called `random()` per
64	  // comparison would not be a consistent ordering, and `Array.sort` on one is
65	  // free to produce anything at all.
66	  const draw = new Map(open.map((i) => [i.number, random()]));
67	
68	  return open
69	    .filter((i) => hasLabel(i, READY) && !hasLabel(i, NEEDS_HUMAN))
70	    .filter((i) => !open.some((o) => o.number !== i.number && titleOf(o) === titleOf(i)
71	      && (hasLabel(o, EXECUTING) || hasLabel(o, AGENT))))
72	    .filter((i) => {
73	      if (!standing(i)) return true;
74	      return !taskAfter(taskIdOf(i)).some(liveUpstream);
75	    })
76	    .sort((a, b) =>
77	      (hasLabel(b, URGENT) ? 1 : 0) - (hasLabel(a, URGENT) ? 1 : 0)
78	      || draw.get(a.number) - draw.get(b.number));
79	}
