81	// The claim comment carries WHO and WHEN — the executor id and its run URL —
82	// because executor identity is an unbounded set and must never become a label
83	// (DESIGN §4).
84	export const claimComment = ({ executor, runUrl, at }) =>
85	  `${CLAIM_MARKER}\nClaimed by executor \`${executor}\` at ${at}.${runUrl ? `\n\nRun: ${runUrl}` : ''}`;
86	
87	// Who won the claim, out of an item's comments (DESIGN §6.2). Three precisions,
88	// each an implicit assumption made explicit:
89	//
90	//  - "EARLIEST" MEANS LOWEST COMMENT ID, never timestamp. GitHub comment
91	//    `created_at` has one-second granularity, so simultaneous claims tie on time;
92	//    comment ids are server-assigned and strictly increasing — a total order the
93	//    protocol gets for free. Nothing here compares runner clocks.
94	//  - THE ARBITER IS EPISODE-SCOPED (F18): the earliest claim SINCE the item last
95	//    became ready. Over an item's lifetime dead claims accumulate (every reclaim
96	//    and revert leaves one), and arbitrating over all of them makes a dead claim
97	//    outrank every future live claimant — the item then livelocks through reclaim
98	//    cycles forever. The reclaim / revert / re-queue comment is the boundary.
99	//  - THE LABEL SWAP IS NOT THE ARBITER, so a torn swap can never mint a second
100	//    owner; it can only leave an item with no state label, which the janitor
101	//    repairs.
102	export function claimWinner(comments = []) {
103	  const sorted = [...comments].sort((a, b) => a.id - b.id);
104	  const boundary = sorted.filter((c) => (c.body ?? '').includes(EPISODE_MARKER)).at(-1);
105	  const claims = sorted
106	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER))
107	    .filter((c) => !boundary || c.id > boundary.id);
108	  return claims[0] ?? null;
109	}
110	
111	// After WINNING a claim, re-verify the pick filters against live state (F15). The
112	// filters read possibly-stale state, so two executors can pass them simultaneously
113	// and claim DIFFERENT items the filters should have serialized — a twin pair, or
114	// an upstream and its dependent. The per-item lease cannot see that: it protects
115	// one item, not one title. If a conflicting item now holds an EARLIER claim
116	// (comment id — the same arbiter the lease trusts), this executor reverts its own
117	// claim and moves on. Bounded, deterministic, and the earlier claim never notices.
118	export function conflictsWithEarlierClaim(item, myClaimId, others, { taskAfter = () => [], frequencyOf = () => null } = {}) {
119	  const standing = (i) => isStandingItem(i, frequencyOf(taskIdOf(i)));
120	  const upstreams = standing(item) ? taskAfter(taskIdOf(item)) : [];
121	  return others.some((o) => {
122	    if (o.number === item.number) return false;
123	    if (!(hasLabel(o, EXECUTING) || hasLabel(o, AGENT))) return false;
124	    const conflicting = titleOf(o) === titleOf(item)
125	      || (upstreams.includes(taskIdOf(o)) && standing(o));
126	    return conflicting && o.claimId != null && o.claimId < myClaimId;
127	  });
128	}
