130	// The no-go outcome (DESIGN §6.4). A SCHEDULED item rolls — `Not-before` stamped
131	// with the task's next anchor, ready → blocked, the reason recorded — so the item
132	// itself carries "asked, declined, wakes at T" and the scheduler run is a pure function of
133	// the clock and the issue list. An AD-HOC item has no next anchor to roll to, so
134	// it closes obsolete with the reason commented (a follow-up whose world settled on
135	// its own, S17).
136	export function noGoPlan(item, task, schedule, now, reason) {
137	  if (!isStandingItem(item, task?.decl?.frequency)) {
138	    return { kind: 'close', outcome: TASK_OBSOLETE, stateReason: 'not_planned', reason };
139	  }
140	  const until = nextAnchor(task.decl.frequency, schedule, now);
141	  return { kind: 'roll', until: until ? until.toISOString() : null, reason };
142	}
