146	const nowIso = () => new Date().toISOString();
147	
148	// ONE EXECUTOR RUN PERFORMS ONE ITEM (DESIGN §6, §10, decision §15.22). Not a
149	// configured maximum — the essence of an executor: it claims one item, sees it to
150	// its settle, and ends. Capacity is executor width, and the queue drains as a
151	// CHAIN of runs, each cause on the record (§10): the scheduler run's own drain job, a
152	// label event, the close-time drain, this run's own `redispatch`, and the
153	// workflow's failure-continuation job when a run dies before reaching it.
154	//
155	// A run that never gets its item — nothing pickable, or another executor holds
156	// this episode's earlier claim — ends without dispatching anything. Retrying a
157	// lost race here would be a second pick attempt racing the very executor that
158	// won, and re-dispatching over a claim we just reverted is a two-executor
159	// dispatch loop; in both cases the winner's own chain (or the scheduler run behind it)
160	// carries the queue.
161	//
162	// Injected seams keep the run testable end to end without GitHub, code-work
163	// subprocesses or an invocation endpoint.
164	export async function runExecutor({
165	  gh, repo, root, config, tasks, executorId, runUrl = null,
166	  now = () => new Date(), random = Math.random, heartbeatMs = HEARTBEAT_MS,
167	  collectSignalsFor, runTaskCodeWork, invokeAgent, redispatch = null, log = console.log,
168	}) {
169	  const api = await import('../github.mjs');
170	  const { listOpenWorkItems } = await import('./read.mjs');
171	  const schedule = config.taskScheduler;
172	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
173	  const taskAfter = (id) => byId.get(id)?.decl?.after ?? [];
174	  const frequencyOf = (id) => byId.get(id)?.decl?.frequency ?? null;
175	  const done = [];
176	
177	  const open = await listOpenWorkItems(gh, repo);
178	  const candidate = pickOrder(open, { taskAfter, frequencyOf, random })[0];
179	  if (!candidate) return done;
180	
181	  // --- claim: the verified lease --------------------------------------------
182	  await api.swapLabel(gh, repo, candidate.number, READY, EXECUTING);
183	  await api.comment(gh, repo, candidate.number, claimComment({
184	    executor: executorId, runUrl, at: nowIso(),
185	  }));
186	  const comments = await api.listComments(gh, repo, candidate.number);
187	  const winner = claimWinner(comments);
188	  const mine = [...comments]
189	    .sort((a, b) => a.id - b.id)
190	    .filter((c) => (c.body ?? '').includes(CLAIM_MARKER) && (c.body ?? '').includes(`executor \`${executorId}\``))
191	    .at(-1);
192	  if (!winner || winner.id !== mine?.id) {
193	    // The loser reverts nothing — the winner's labels already stand. It does
194	    // strike its own claim (F24): letting go covers losing too, and a claim left
195	    // behind here outlives the winner's episode and becomes the earliest of the
196	    // NEXT one, moving the livelock one episode along.
197	    await strikeClaim(api, gh, repo, mine);
198	    log(`- #${candidate.number}: another executor holds this episode's earliest claim — this run stands down`);
199	    return done;
200	  }
201	
202	  // --- post-claim re-verify (F15) -------------------------------------------
203	  const others = await withClaimIds(api, gh, repo, await listOpenWorkItems(gh, repo), candidate.number);
204	  if (conflictsWithEarlierClaim(candidate, winner.id, others, { taskAfter, frequencyOf })) {
205	    await api.comment(gh, repo, candidate.number,
206	      `${EPISODE_MARKER}\nReverting this claim: a conflicting item holds an earlier claim this cycle. Returning the item to the queue.`);
207	    await api.swapLabel(gh, repo, candidate.number, EXECUTING, READY);
208	    log(`- #${candidate.number}: reverted — a conflicting item claimed earlier`);
209	    return done;
210	  }
211	
212	  const outcome = await executeItem({
213	    api, gh, repo, root, config, schedule, byId, item: candidate, executorId,
214	    claim: winner, now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
215	  });
216	  done.push({ issue: candidate.number, outcome });
217	
218	  // --- the chain: hand the remainder to a fresh run -------------------------
219	  // Read live, after the settle: this item's convergence may have readied a
220	  // dependent, and another executor may have taken what was pickable when this
221	  // run started.
222	  if (redispatch) {
223	    const left = pickOrder(await listOpenWorkItems(gh, repo), { taskAfter, frequencyOf, random });
224	    if (left.length) {
225	      const res = await redispatch();
226	      log(res?.ok
227	        ? `- ${left.length} item(s) still pickable — dispatched a fresh executor run`
228	        : `! ${left.length} item(s) still pickable but the re-dispatch failed (${res?.status ?? 'no status'}) — the scheduler run's drain is the backstop`);
229	    }
230	  }
231	  return done;
232	}
