234	// The claim id of each live item, so the post-claim verify can compare episodes.
235	// One comment read per conflicting-looking item, not per item in the repo.
236	async function withClaimIds(api, gh, repo, items, selfNumber) {
237	  const out = [];
238	  for (const i of items) {
239	    if (i.number === selfNumber || !(hasLabel(i, EXECUTING) || hasLabel(i, AGENT))) { out.push(i); continue; }
240	    const winner = claimWinner(await api.listComments(gh, repo, i.number));
241	    out.push({ ...i, claimId: winner?.id ?? null });
242	  }
243	  return out;
244	}
