246	// One claimed item, from validation through to a terminal state (or a hand-off).
247	async function executeItem({
248	  api, gh, repo, root, config, schedule, byId, item, executorId, claim,
249	  now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log,
250	}) {
251	  // What a close needs beyond the item itself: the clock for a dependent's
252	  // `Not-before`, and somewhere to say what it released.
253	  const ctx = { now, log };
254	  const parsed = parseWorkItemTitle(item.title);
255	  const { taskPath } = parseWorkItemBody(item.body);
256	  const id = parsed ? `${parsed.pack}/${parsed.task}` : null;
257	  const task = id ? byId.get(id) : null;
258	
259	  // --- validate in code, before anything trusts the issue ------------------
260	  if (!parsed || !taskPath) {
261	    await converge(api, gh, repo, item, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
262	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.', 'invalid');
263	    return 'needs-human';
264	  }
265	  if (!task) {
266	    await close(api, gh, repo, item, EXECUTING, TASK_OBSOLETE, 'not_planned',
267	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`, 'task-gone', ctx);
268	    return 'obsolete';
269	  }
270	  if (task.taskPath !== taskPath) {
271	    await converge(api, gh, repo, item, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
272	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
273	    return 'needs-human';
274	  }
275	
276	  // --- the single precondition evaluation (DESIGN §6.4) --------------------
277	  const at = now();
278	  const fields = parseWorkItemBody(item.body);
279	  // The signals are collected FOR THIS OCCURRENCE, and the precondition judges over
280	  // it: a request item's verdict is about the issue it names, which no signal bundle
281	  // can single out on its own (DESIGN §16.4).
282	  const signals = await collectSignalsFor(task, at, item);
283	  const verdict = evaluatePrecondition(task, signals, config.packConfig?.[task.pack] ?? {}, fields);
284	
285	  // A PRECONDITION THAT COULD NOT ANSWER IS A RUN FAILURE, NOT A VERDICT (F27). A
286	  // decline is a decision about the world; one taken on an API that would not answer
287	  // is a guess, and its write-backs cannot land — for a request that would strand
288	  // the issue armed-but-queued forever, the request silently eaten. So the item
289	  // parks open in the failure lane, where the ordinary re-queue lever retries it
290	  // once the API recovers, and nothing is written to whatever it could not read.
291	  if (verdict.error) {
292	    await converge(api, gh, repo, item, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
293	      `This run could not be decided: ${verdict.error}\n\nNothing ran and nothing was written. Re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`) once the cause has cleared.`);
294	    log(`! #${item.number} ${id}: the precondition could not answer — ${verdict.error}`);
295	    return 'needs-human';
296	  }
297	
298	  if (verdict.run !== true) {
299	    const plan = noGoPlan(item, task, schedule, at, verdict.reason || 'no work');
300	    if (plan.kind === 'close') {
301	      // A DECLINED REQUEST IS DISARMED IN THE SAME CONVERGENCE (DESIGN §16.5).
302	      // Nothing else would: an issue left carrying `claude-queued` after its run was
303	      // refused is one no later scheduler run adopts and no person is told about, and one
304	      // whose mark — if re-applied — walks into the same refusal forever.
305	      if (fields.request) await declineRequest(api, gh, repo, fields.request, item.number, plan.reason);
306	      // A DECLINE IS A COMPLETED RUN, not a failure: the executor asked, got a
307	      // no, and closed the occurrence — so the record says `success` and the
308	      // reason sits beside it in the same comment.
309	      await close(api, gh, repo, item, EXECUTING, TASK_OBSOLETE, 'not_planned',
310	        `The precondition declined and this item has no anchor to roll to: ${plan.reason}`, 'success', ctx);
311	      return 'obsolete';
312	    }
313	    // The roll writes no comment — the `Not-before` bump IS the record, and an
314	    // hourly task that stays quiet would otherwise fill its own timeline (§5).
315	    // Which is exactly why the claim is STRUCK rather than closed by a marker
316	    // comment: the episode has to end here (F24) without costing a timeline entry.
317	    await strikeClaim(api, gh, repo, claim);
318	    await gh(`/repos/${repo}/issues/${item.number}`, {
319	      method: 'PATCH',
320	      body: { body: rollBody(item.body, plan.until, plan.reason, at.toISOString()) },
321	    });
322	    await api.swapLabel(gh, repo, item.number, EXECUTING, BLOCKED);
323	    log(`- #${item.number} ${id}: rolled to ${plan.until} — ${plan.reason}`);
324	    return 'rolled';
325	  }
326	
327	  // --- code-work (unchanged contract), then converge or hand off -------------
328	  // The item's OWN Context is scope too, not decoration: an operator's parameters
329	  // (`create-work-item --context "REPOS=Alpha Beta"`) live there and nowhere else,
330	  // so code-work sees the union of what the item was created with and what this
331	  // occurrence's precondition added. Passing only the verdict's half is what made
332	  // a hand-created item's parameters unreachable (#974).
333	  const context = mergeContext(parseContextLines(item.body), verdict.context ?? []);
334	  if (task.decl.code_work) {
335	    // The work step may legitimately run for hours (§15.15). While it does, the
336	    // item's only sign of life is this beat — which is also what the scheduler run's leash
337	    // measures, so a long run is legal rather than reclaimed underneath itself.
338	    const result = await withHeartbeat(() => runTaskCodeWork(task, { item, context }), {
339	      intervalMs: heartbeatMs,
340	      log,
341	      beat: (minutes) => api.comment(gh, repo, item.number,
342	        heartbeatComment({ executor: executorId, at: nowIso(), minutes })),
343	    });
344	    if (!result.ok) {
345	      // The worker's own verdict routes the park where it left one; a worker that
346	      // said nothing about why it failed is a `failure` — the lane that means
347	      // "someone reads the trace", which is the only safe default for a run whose
348	      // cause is unknown.
349	      await converge(api, gh, repo, item, EXECUTING, triageLabelFor(result.triage?.kind), claim,
350	        `Code-work failed: ${result.why}${result.triage?.detail ? `\n\nThe worker's own verdict: ${result.triage.detail}` : ''}`
351	        + `${result.detail ? `\n\n\`\`\`\n${result.detail}\n\`\`\`` : ''}`);
352	      return 'needs-human';
353	    }
354	    if (result.missingSecrets?.length) {
355	      await converge(api, gh, repo, item, EXECUTING, NEEDS_HUMAN_ACTION, claim,
356	        `This task declares repo Actions secrets that are not configured: ${result.missingSecrets.join(', ')}. Set them in repo settings and re-queue this item (remove the \`needs-human\` labels, add \`task:ready\`).`);
357	      return 'needs-human';
358	    }
359	    if (!result.agentRequested) {
360	      // A run that deliberately left an UNMERGED PR is not finished, it is waiting
361	      // on a person — so the item stays OPEN at `task:needs-human-approval` rather
362	      // than closing as delivered. It does not hold the task's lane while it waits
363	      // (`isBlockingPark`): the next occurrence is filed on schedule around it, so
364	      // an unreviewed PR delays nobody but its reviewer.
365	      if (result.openPr) {
366	        await converge(api, gh, repo, item, EXECUTING, NEEDS_HUMAN_APPROVAL, claim,
367	          `Code-work did this run's work and opened a PR for you to approve:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
368	          + `\n\nMerge or close #${result.openPr}, then close this item. This task keeps running on schedule meanwhile.`, null);
369	        return 'needs-human';
370	      }
371	      await close(api, gh, repo, item, EXECUTING, TASK_DONE, 'completed',
372	        result.delivered?.length
373	          ? `Code-work did this run's work and left:\n${result.delivered.map((d) => `- ${d}`).join('\n')}`
374	          : 'Code-work did this run\'s work; no agent was needed.', 'success', ctx);
375	      return TASK_DONE;
376	    }
377	    return handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log });
378	  }
379	
380	  // An agentless task with no code-work does nothing (the contract forbids it).
381	  if (task.decl.agent_model === 'none') {
382	    await converge(api, gh, repo, item, EXECUTING, NEEDS_HUMAN_FAILURE, claim,
383	      'This task is agentless but declares no code_work, so there is nothing to run — a contract-forbidden shape that reached the queue.', 'invalid');
384	    return 'needs-human';
385	  }
386	  return handOff({ api, gh, repo, item, task, id, context, result: {}, executorId, claim, invokeAgent, config, log });
387	}
388	
389	// The roll's body edit: stamp the next anchor and keep the last reason where an
390	// operator reads it. The reason REPLACES the previous one — the item is a status
391	// line, not a log; its timeline carries the history.
392	// Run one task's precondition. THE only place a precondition is ever called, so a
393	// test that drives this drives what production drives — a precondition first
394	// written to take `{ signals }` passed its own direct-call test and threw on every
395	// real run, which is the failure this seam exists to make impossible.
396	//
397	// A throwing precondition converges to a no-go with the error as its reason: one
398	// task's bad verdict is that item's problem, never the executor's.
399	export function evaluatePrecondition(task, signals, packConfig = {}, item = null) {
400	  try {
401	    return task.decl.precondition(signals, packConfig, item) ?? {};
402	  } catch (e) {
403	    return { run: false, reason: `precondition threw: ${e.message}` };
404	  }
405	}
406	
407	// The write-back a refused request gets (DESIGN §16.5): one comment saying why, and
408	// the queued label off, so the request is disarmed rather than left looking pending.
409	// It is the executor's because the executor is what converged the item — whoever
410	// converges owns the write-back for the end they converged.
411	async function declineRequest(api, gh, repo, request, item, reason) {
412	  await api.comment(gh, repo, request,
413	    `Not implementing this: ${reason}\n\nThe queued run (#${item}) is closed and \`${QUEUED_LABEL}\` is removed. `
414	    + 'If this was wrong, mark the issue again — a request is only run when the person who opened it, or somebody who commented `/claude go`, has push access here.');
415	  await api.removeLabel(gh, repo, request, QUEUED_LABEL);
416	}
417	
418	export function rollBody(body, until, reason, at) {
419	  const stamped = withNotBefore(body, until);
420	  return withSection(stamped, LAST_VERDICT_HEADING, lastVerdictLines({ at, reason, until }));
421	}
422	
423	// Hand off to an agent session (DESIGN §6.6). ONE call per item, ever — which is
424	// what lets this be as short as it is. The nonce goes on the item before the call
425	// and travels in the payload, so the session can prove the fire it arrived on is
426	// the hand-off this item recorded and stop if it is not.
427	async function handOff({ api, gh, repo, item, task, id, context, result, executorId, claim, invokeAgent, config, log }) {
428	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
429	  let body = item.body;
430	  if (context.length) body = withSection(body, 'Context', context);
431	  if (result.delivered?.length) body = withSection(body, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
432	  if (result.reason) body = withSection(body, 'Why the agent is here', [result.reason]);
433	  await gh(`/repos/${repo}/issues/${item.number}`, { method: 'PATCH', body: { body } });
434	
435	  await api.swapLabel(gh, repo, item.number, EXECUTING, AGENT);
436	  await api.comment(gh, repo, item.number,
437	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
438	
439	  const invocation = await invokeAgent({ task, item, nonce, config });
440	  if (invocation.ok) {
441	    await api.comment(gh, repo, item.number,
442	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
443	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
444	    return 'agent';
445	  }
446	  if (invocation.answered) {
447	    // The endpoint refused, so no session exists and none will: a token, a URL or
448	    // a routine is wrong, and every future pick would be refused the same way.
449	    await converge(api, gh, repo, item, AGENT, NEEDS_HUMAN_ACTION, claim,
450	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (remove the \`${NEEDS_HUMAN}\` labels, add \`${READY}\`).`);
451	    return 'needs-human';
452	  }
453	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
454	  // may have started a session. Re-queueing here is what would put two sessions on
455	  // one item, and converging to triage would kill a run that is very possibly
456	  // alive. So the item STAYS with the agent and says the outcome is unknown —
457	  // whichever way it went is then settled by a rule that already exists: a session
458	  // that started converges the item, and one that never did leaves the item silent
459	  // until the janitor's agent leash sweeps it to triage.
460	  await api.comment(gh, repo, item.number,
461	    `The agent invocation got no answer: ${invocation.error}\n\n`
462	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
463	    + `If a session did start it will converge this item; if it did not, the janitor's agent leash brings this item to \`${NEEDS_HUMAN}\` within a few hours.`);
464	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
465	  return 'unknown';
466	}
467	
468	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (DESIGN §6.2, F24). An executor
469	// that stops owning an item without closing it — the roll, and every
470	// `needs-human` park — strikes its own claim by appending the episode marker to
471	// it. `claimWinner` already treats the last marker as the boundary, so a struck
472	// claim stops outranking anything and the next claimant wins on its first try.
473	//
474	// APPENDING rather than commenting is what lets the roll stay silent (§5): an
475	// hourly task that declines every hour adds no timeline entry. A successful
476	// hand-off deliberately does NOT strike — the episode is still live, owned by the
477	// agent session — and neither does a close, since nothing re-claims a closed item.
478	//
479	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
480	// executor that dies between the two leaves the item `task:executing` with a
481	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
482	// would leave exactly the state this fixes — parked, re-queued by a human, and
483	// unclaimable forever.
484	async function strikeClaim(api, gh, repo, claim) {
485	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
486	  await api.editComment(gh, repo, claim.id,
487	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
488	}
489	
490	// Every exit converges the item exactly once, with one comment saying what
491	// happened — the terminal-state discipline the incidents bought. The claim sits
492	// before the body so every state argument is grouped ahead of the prose.
493	//
494	// THE COMMENT CARRIES THE EXECUTION RECORD (DESIGN §6.5, §15.18). Actions logs
495	// expire, and for an agentless run — the majority — the item is the only durable
496	// trace there will ever be, so the record goes where the item is rather than into
497	// a log that ages out. The bracketed field is this item's issue number, which is
498	// the only join from a record back to the work it describes.
499	// A status of `null` writes NO record, and that is the honest answer for a park
500	// that is not a failure: the vocabulary's `success` means "ran to completion and
501	// the issue was closed" and `failed` means the run broke, so an approval park —
502	// a run that succeeded and left a PR for a person — is neither. Absence is a
503	// state of its own; inventing a fifth status is a change to stored data every
504	// decoder in the fleet would have to learn.
505	const recordFor = (item, status) => {
506	  const parsed = status ? parseWorkItemTitle(item.title) : null;
507	  return parsed
508	    ? `\n\n\`\`\`\n${renderTaskExec({ pack: parsed.pack, task: parsed.task, slotId: `#${item.number}`, status })}\n\`\`\``
509	    : '';
510	};
511	
512	// Park an item for a human. BOTH labels, always: `needs-human` is the state every
513	// guard and sweep reads, `triage` is what the human is being asked for.
514	async function converge(api, gh, repo, item, from, triage, claim, body, status = 'failed') {
515	  await strikeClaim(api, gh, repo, claim);
516	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
517	  await api.swapLabel(gh, repo, item.number, from, NEEDS_HUMAN);
518	  await api.addLabel(gh, repo, item.number, triage);
519	}
520	
521	// A close is also the moment a dependent may become due (§15.19): whoever closes
522	// an item releases what it was holding, in code, and the run's own re-dispatch
523	// then finds it. The scheduler run stays the backstop for every close this code never
524	// performs — a human's, or a session that stopped early.
525	async function close(api, gh, repo, item, from, outcome, stateReason, body, status, ctx = {}) {
526	  await api.comment(gh, repo, item.number, body + recordFor(item, status));
527	  await api.removeLabel(gh, repo, item.number, from);
528	  await api.addLabel(gh, repo, item.number, outcome);
529	  await api.closeIssue(gh, repo, item.number, stateReason);
530	  await readyDependents(api, gh, repo, item.number, ctx);
531	}
532	
533	// --- CLI ----------------------------------------------------------------------
534	
535	async function main() {
536	  // THE OPERATOR HOLD, FIRST ACT (§15.24) — before the config load, before the
537	  // first API call, so a held queue reads nothing and writes nothing rather than
538	  // deriving the world and then declining to act on it.
539	  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
540	  const { makeGh, actionRepoContext, EXECUTOR_WORKFLOW_FILE } = await import('../signals/gh.mjs');
541	  const { discoverTasks } = await import('../discover.mjs');
542	  const { loadConfig, isDormant } = await import('../../checks/helpers/repo-context.mjs');
543	  const { ensureLabels, dispatchWorkflow } = await import('../github.mjs');
544	  const { collectSignalsForTask } = await import('./signals.mjs');
545	  const { codeWorkRunner } = await import('./code-work-run.mjs');
546	  const { agentInvoker } = await import('./invoke.mjs');
547	
548	  const root = process.cwd();
549	  const { repo, defaultBranch } = actionRepoContext();
550	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
551	  const config = loadConfig(root);
552	
553	  console.log('## Claudinite executor\n');
554	  if (isDormant(config)) {
555	    console.log('- this project declares itself dormant — nothing is picked up');
556	    return;
557	  }
558	
559	  const gh = makeGh();
560	  const { tasks, errors } = await discoverTasks(root, config);
561	  for (const e of errors) console.log(`! ${e.what}`);
562	  await ensureLabels(gh, repo, [...QUEUE_LABELS, ...REQUEST_LABELS]);
563	
564	  const runUrl = process.env.GITHUB_RUN_ID
565	    ? `${process.env.GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${process.env.GITHUB_RUN_ID}`
566	    : null;
567	
568	  const done = await runExecutor({
