1	// Anchors — when a task's occurrence falls (tasks-dispatch DESIGN §5).
2	//
3	// The arithmetic lives in `calendar.mjs`; this module exposes exactly the two
4	// questions the queue asks of it — "which occurrence is current" (the scheduler run's
5	// instantiation guard) and "when does this item wake next" (the roll's stamped
6	// `Not-before`) — plus the period a frequency repeats on.
7	//
8	// Pure and stateless: `now` is always injected, every value is UTC.
9	
10	import { anchorInstant } from '../calendar.mjs';
11	
12	const HOUR_MS = 3600e3;
13	const DAY_MS = 24 * HOUR_MS;
14	
15	// One period of a frequency, in ms — the unit the janitor's stale-ready rule
16	// counts in (DESIGN §11) and the coarse step `nextAnchor` walks.
17	export function periodMs(frequency) {
18	  if (frequency === 'hourly') return HOUR_MS;
19	  if (frequency === 'weekly') return 7 * DAY_MS;
20	  if (frequency === 'monthly') return 31 * DAY_MS;
21	  if (frequency === 'manual') return null;
22	  return DAY_MS; // the daily family
23	}
24	
25	// The most recent occurrence at or before `now`, as a Date. `manual` has none —
26	// the scheduler run never instantiates it (DESIGN §8), so null is the whole answer.
27	export const mostRecentAnchor = anchorInstant;
28	
29	// The earliest occurrence strictly after `now` — what a rolled item is stamped
30	// with. Derived by walking `mostRecentAnchor` forward rather than by adding a
31	// period: monthly anchors are not a fixed distance apart, and a `daily-2h` whose
32	// instant wraps to the previous calendar day is exactly the case a fixed add gets
33	// wrong. The coarse step is under one period, so the loop advances by at most two
34	// steps and never overshoots an occurrence.
35	export function nextAnchor(frequency, schedule, now) {
36	  if (frequency === 'manual') return null;
37	  const from = mostRecentAnchor(frequency, schedule, now).getTime();
38	  const step = frequency === 'monthly' ? 28 * DAY_MS : periodMs(frequency);
39	  for (let t = from + step; ; t += step) {
40	    const candidate = mostRecentAnchor(frequency, schedule, new Date(t));
41	    if (candidate.getTime() > from) return candidate;
42	  }
43	}
44

1	// Signal collection for ONE picked task (tasks-dispatch DESIGN §5, §6.4). The
2	// scheduler run performs no GitHub read beyond the issue list, so the whole cost of
3	// signals moved here — where exactly one task's declared union is collected, once
4	// per period per task, at the moment its verdict is asked for.
5	//
6	// The lookback is that task's own period plus an hour of slack: stateless, and
7	// overlap is absorbed by the preconditions' own dedupe, exactly as the slot
8	// scheduler's window did for the widest due task.
9	
10	import { periodMs } from './anchors.mjs';
11	import { parseWorkItemBody } from './work-item.mjs';
12	
13	export const windowStart = (task, now) =>
14	  new Date(new Date(now).getTime() - (periodMs(task.decl.frequency) ?? 86400e3) - 3600e3).toISOString();
15	
16	// A collector factory bound to this run's repo context; the returned function is
17	// the `collectSignalsFor` seam the executor calls.
18	export function collectSignalsForTask({ gh, repo, root, config, defaultBranch }) {
19	  return async function collectFor(task, now, item = null) {
20	    const { collectSignals } = await import('../signals/index.mjs');
21	    const { buildSignalContext } = await import('../signals/context.mjs');
22	    const names = task.decl.precondition_signals ?? [];
23	    const packConfigFor = (packId) => config.packConfig?.[packId] ?? {};
24	    const sinceIso = windowStart(task, now);
25	
26	    // The fleet aggregate is a full enumeration over a wider credential, so it is
27	    // built only when THIS task declares it and only where that credential exists.
28	    // Absent, the collector returns null and a fleet task's precondition declines
29	    // rather than crashing.
30	    let fleet = null;
31	    if (names.includes('fleet')) {
32	      const { readFleet, makeFleetGh } = await import('../signals/fleet.mjs');
33	      const fleetGh = makeFleetGh();
34	      if (fleetGh) {
35	        fleet = await readFleet(fleetGh, { owner: repo.split('/')[0], canonRepo: repo, sinceIso });
36	        if (fleet.error) console.log(`! fleet enumeration: ${fleet.error}`);
37	      } else {
38	        console.log('- this task declares the `fleet` signal but FLEET_GITHUB_TOKEN is not set');
39	      }
40	    }
41	
42	    const ctx = buildSignalContext({
43	      root, repo, defaultBranch, now: new Date(now).toISOString(), sinceIso, config, fleet, packConfigFor,
44	      // The occurrence's own facts, for the collector that reads one named object
45	      // rather than a window (the request read, DESIGN §16.4).
46	      item: item ? parseWorkItemBody(item.body) : null,
47	    });
48	    return collectSignals(gh, ctx, names);
49	  };
50	}
