16	// A default-branch commit is genuine project work unless it is bot/CI
17	// housekeeping or one of Claudinite's own automated writes — the same exclusions
18	// the fleet planner applies (kept in sync), extended with the scheduler's own
19	// `[claudinite-task]` and `[claudinite-work]` writes so neither dispatch
20	// mechanism ever self-triggers. The queue's vocabulary is excluded HERE, before
21	// any repo flips (tasks-dispatch F8): a queue-mode repo's own work items are
22	// repo activity to every precondition watching issues, so a collector that had
23	// not learned the new title would wake tasks on the queue's own churn.
24	const HOUSEKEEPING = /\[skip ci\]|(^|\n)\s*baselin(e|ing)\b|claudinite[ -](baselin|maintenance|growth|task|work)|seed default-on/i;
25	
26	// …and a THIRD exclusion the message cannot express: a commit that touched
27	// nothing outside `.claudinite/` moved the repo's own working rules, not the
28	// project. Every consumer of `substantiveChange` means "genuine project work" by
29	// it — an issue was implemented (tidy-issues), something shippable changed
30	// (store-release), there is a lesson to extract (growth-extract) — and none of
31	// those is true of a corpus edit. Message and author cannot catch it: a human
32	// landing a lesson PR writes an ordinary message under their own login, so the
33	// growth lifecycle's own landed output re-armed it the next night and a repo
34	// could never go quiet (TLDR #319).
35	//
36	// `files` is `[]` when the commit's detail read failed, which is UNKNOWN, not
37	// "touched only .claudinite/" — a bare `every` is vacuously true on it and would
38	// silently retire the trigger for every commit the API would not detail. Require
39	// at least one known path before the exclusion can apply.
40	const CORPUS_ONLY = (files) => files.length > 0 && files.every((f) => f.startsWith('.claudinite/'));
41	const isSubstantive = (c, files) => {
42	  const login = c.author?.login ?? '';
43	  if (login.endsWith('[bot]')) return false;
44	  if (CORPUS_ONLY(files)) return false;
45	  return !HOUSEKEEPING.test(c.commit?.message ?? '');
46	};
