77	// Like `paged`, but for a listing sorted `updated` DESCENDING and bounded by the
78	// window: it stops at the first item outside it and does not fetch the next page.
79	// The closed-PR listing is otherwise the repo's whole history — a window read must
80	// not cost proportionally to that.
81	async function pagedWindow(gh, path, inWindow) {
82	  const out = [];
83	  for (let page = 1; ; page += 1) {
84	    const sep = path.includes('?') ? '&' : '?';
85	    const { status, json } = await gh(`${path}${sep}per_page=100&page=${page}`);
86	    if (status !== 200 || !Array.isArray(json) || json.length === 0) break;
87	    const kept = [];
88	    for (const item of json) {
89	      if (!inWindow(item)) break;
90	      kept.push(item);
91	    }
92	    out.push(...kept);
93	    if (kept.length < json.length || json.length < 100) break;
94	  }
95	  return out;
96	}
