112	// Commit objects in the window, with their changed-file lists resolved (one read
113	// per commit — the window is a handful of commits).
114	async function windowCommits(gh, repo, branch, sinceIso) {
115	  const list = await paged(gh, `/repos/${repo}/commits?sha=${encodeURIComponent(branch)}&since=${sinceIso}`);
116	  const detailed = [];
117	  for (const c of list) {
118	    const d = await gh(`/repos/${repo}/commits/${c.sha}`);
119	    const files = d.status === 200 ? (d.json?.files ?? []).map((f) => f.filename).filter(Boolean) : [];
120	    detailed.push({ sha: c.sha, message: c.commit?.message ?? '', author: c.author?.login ?? null, substantive: isSubstantive(c, files), files });
121	  }
122	  return detailed;
123	}
