136	  async prs(gh, ctx) {
137	    const open = await paged(gh, `/repos/${ctx.repo}/pulls?state=open&sort=updated&direction=desc`);
138	    const since = new Date(ctx.sinceIso);
139	
140	    // PRs MERGED during the window, in a field of their OWN. A merged PR carries
141	    // the review discussion and the "what changed and why" — usually the richest
142	    // lesson material in a window — and `state=open` alone made it unreachable to
143	    // any task bound to this signal. It is deliberately NOT folded into `open` or
144	    // `touched`: those two are other tasks' target sets (the PR tidy sweep acts on
