267	    const { status, json } = await gh(`/repos/${ctx.repo}/git/trees/conversation-logs`);
268	    const stamps = (status === 200 && Array.isArray(json?.tree) ? json.tree : [])
269	      .map((e) => logStampMs(e?.path ?? ''))
270	      .filter((ms) => ms !== null);
271	    const now = new Date(ctx.now).getTime();
272	    const oldestLogAgeDays = stamps.length && Number.isFinite(now)
273	      ? (now - Math.min(...stamps)) / 86400000
