293	  // THE REQUEST READ (tasks-dispatch DESIGN §16.4). Unlike every collector beside
294	  // it, this one reads a single named object rather than a window: the issue THIS
295	  // item was created for, off `ctx.item.request`. That is what the precondition's
296	  // third argument buys — a verdict about one issue, which no window of repo
297	  // activity can single out.
298	  //
299	  // It reads facts and forms no judgment: who asked, who blessed it with the
300	  // approval phrase, and what PERMISSION each of them holds — never whether that is
301	  // enough. The rule lives in the task's precondition, where every other verdict is.
302	  //
303	  // Three shapes of answer, and the difference between the last two is the whole of
304	  // F27: `gone` (the API says it does not exist) is a fact a precondition can
305	  // decline on, while `unreadable` (a rate limit, a 500) is one it must NOT — a
306	  // decline's write-back cannot reach an issue it cannot read.
307	  async request(gh, ctx) {
308	    const number = ctx.item?.request ?? null;
309	    if (!number) return null;
310	    const { status, json } = await gh(`/repos/${ctx.repo}/issues/${number}`);
311	    if (status === 404 || status === 410) return { number, gone: true };
312	    if (status !== 200 || !json) return { number, unreadable: true, error: `the issues API answered ${status}` };
313	
314	    // The permission API is the authority, never the payload's `author_association`:
315	    // `MEMBER` is any org member whatever their repo permission, and `COLLABORATOR`
316	    // includes read-only collaborators — both broader than push (F30). A read that
317	    // fails is unreadable, not "no permission": guessing downward here would refuse
318	    // a legitimate request over a rate limit.
319	    const permissions = new Map();
320	    let failed = null;
321	    const permissionOf = async (login) => {
322	      if (!login) return 'none';
323	      if (permissions.has(login)) return permissions.get(login);
324	      const res = await gh(`/repos/${ctx.repo}/collaborators/${encodeURIComponent(login)}/permission`);
325	      // A 403/404 here is a real answer: the caller may not read collaborators, or
326	      // this login is not one. The first is a repo-configuration fault and the
327	      // second is the ordinary "a stranger opened it" case, and only the API can
328	      // tell them apart — so a 404 is `none` and anything else stops the read.
329	      let value;
330	      if (res.status === 200) value = res.json?.role_name ?? res.json?.permission ?? 'none';
331	      else if (res.status === 404) value = 'none';
332	      else { failed = `the permission API answered ${res.status} for @${login}`; value = 'none'; }
