337	    const author = json.user?.login ?? null;
338	    const authorPermission = await permissionOf(author);
339	    // The approval phrase is only worth a permission read on the comments that
340	    // carry it, so an issue with a long thread costs one read per distinct blesser.
341	    const comments = await paged(gh, `/repos/${ctx.repo}/issues/${number}/comments`);
