344	      const login = c.user?.login ?? null;
345	      if (!login || !APPROVAL_RE.test(c.body ?? '')) continue;
346	      approvals.push({ login, permission: await permissionOf(login) });
347	    }
348	    if (failed) return { number, unreadable: true, error: failed };
349	
350	    return {
351	      number,
352	      state: json.state,
353	      labels: (json.labels ?? []).map((l) => l.name ?? l),
354	      queued: (json.labels ?? []).map((l) => l.name ?? l).includes(QUEUED_LABEL),
355	      author,
356	      authorPermission,
357	      approvals,
358	    };
359	  },
360	
361	  async fleet(gh, ctx) {
362	    return ctx.fleet ?? null;
363	  },
364	};
