368	// Collect exactly the requested signal names into one object. An unknown name is
369	// ignored (the task-declaration-shape check rejects those at author time); a
370	// collector that throws records `{ error }` under its key rather than sinking the
371	// whole collection (per-signal isolation).
372	export async function collectSignals(gh, ctx, names) {
373	  const out = {};
374	  // Commit-derived collectors share one window read.
375	  if (names.some((n) => ['commits', 'localPacks', 'sharedMount'].includes(n)) && !ctx.commits) {
376	    try { ctx = { ...ctx, commits: await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso) }; } catch { /* collectors re-read on demand */ }
377	  }
378	  for (const name of names) {
379	    const collect = COLLECTORS[name];
380	    if (!collect) continue;
381	    try { out[name] = await collect(gh, ctx); }
382	    catch (e) { out[name] = { error: e.message }; }
383	  }
384	  return out;
385	}
