111	export function makeSim({
112	  tasks,
113	  afterMode = 'yield', // 'yield' (the design) | 'blocked-by' (S24's rejected wiring)
114	  schedulerRunMinute = 17,
115	  executingLeashMs = 1 * HOUR,
116	  agentLeashMs = 3 * HOUR,
117	  heartbeatMinutes = 15, // the executor's activity comment cadence during the work step
118	  pickSeed = 1, // seed for the randomized pick order, so scenarios replay identically
119	  staleReadyPeriods = 2,
120	  staleBlockedMs = 2 * DAY,
121	  heartbeatsDisabled = false, // S31b only: demonstrate the livelock heartbeats prevent
122	  collaborators = { owner: 'admin' }, // login -> repo permission, as the permission API answers (F30)
123	} = {}) {
124	  const registry = new Map(tasks.map((t) => [t.id, t]));
125	  const permissionOf = (login) => collaborators[login] ?? 'none';
126	  // Ordinary issues somebody marked — NOT work items, and never wearing a
127	  // `task:` label. Their own small vocabulary is the whole request state.
128	  const requests = []; // {number,labels:Set,state,author,unreadable,comments:[{login,body}]}
129	  // A deleted issue ('gone') is invisible here, exactly as a 404 makes it: the
130	  // precondition sees "does not exist", and no write-back can reach it.
131	  const requestOf = (n) => requests.find((r) => r.number === n && r.state !== 'gone') ?? null;
132	  const titleOf = (id) => `[claudinite-work] ${id}`;
133	
134	  // The built-in request task, always present wherever the queue runs (DESIGN
135	  // §16.2): `manual`, so the scheduler run never puts it on a calendar — an item exists
136	  // only because an issue was marked. Its precondition IS the security check, and
137	  // it declares no code-work at all, so a request goes issue → item → agent with
138	  // nothing in between to carry a payload.
139	  registry.set(REQUEST_TASK, {
140	    id: REQUEST_TASK,
141	    frequency: 'manual',
142	    agentMinutes: 45,
143	    ceiling: 'open-pr',
144	    deliversOpenPr: () => true,           // every successful run leaves a PR to review
145	    // Evaluated at pickup like every other precondition, and — the one addition
146	    // the contract needs — over THIS item, because which request it is about is a
147	    // property of the item, not of the task.
148	    precondition: (_world, _now, item) => {
149	      const req = requestOf(item?.request);
150	      // Transiently unreadable is NOT a verdict (F27): a decline's write-back
151	      // cannot reach an issue it cannot read, so declining here would strand
152	      // `claude-queued` forever over nothing. It surfaces as a run FAILURE —
153	      // the executor parks the item in the failure lane, open and retryable.
154	      if (req?.unreadable) return { error: `issue #${req.number} could not be read — refusing to guess` };
155	      if (!req) return { run: false, reason: `issue #${item?.request} does not exist` };
156	      if (req.state !== 'open') return { run: false, reason: `issue #${req.number} was closed before this ran` };
157	      if (!req.labels.has(QUEUED_LABEL)) return { run: false, reason: `issue #${req.number} no longer carries the queued label — the request was withdrawn` };
158	      const verdict = eligible(req, permissionOf);
159	      return verdict.ok
160	        ? { run: true, reason: `#${req.number}: ${verdict.why}` }
161	        : { run: false, reason: `#${req.number}: ${verdict.why}` };
162	    },
163	  });
164	
165	  // F17, reframed by the work-as-work review (2026-08-15): the leash no longer
166	  // has to exceed every task's work bound — heartbeat comments during the work
167	  // step keep a LIVE executor's item out of the reclaim, however long the work
168	  // runs, so the leash measures executor death, not work duration. The wiring
169	  // constraint that remains is the one the heartbeat itself needs: the
170	  // heartbeat interval must sit well inside the leash, or every heartbeat
171	  // arrives too late to matter.
172	  if (heartbeatMinutes * MIN >= executingLeashMs) {
173	    throw new Error(
174	      `heartbeat interval (${heartbeatMinutes}m) reaches the executing leash — F17 (reframed)`);
175	  }
176	
177	  const issues = []; // {number,title,taskId,labels:Set,state,createdAt,closedAt,readySince,lastActivity,notBefore,blockedBy:[],outcome,rolls:[],comments:[],escalated,sessions:[],quarantined}
178	  const log = []; // {t,kind,task,issue,...}
179	  const world = {}; // scenario-owned signal state, read by precondition fns
180	  const queue = []; // {t,seq,fn}
181	  let seq = 0;
182	  let now = 0;
183	  let sessionSeq = 0;
184	  // Randomized pick order (owner, 2026-08-15) wants randomness; reproducible
185	  // tests want determinism. A seeded LCG gives both.
186	  let prngState = pickSeed >>> 0;
187	  const prng = () => (prngState = (prngState * 1664525 + 1013904223) >>> 0) / 2 ** 32;
188	  // CLAUDINITE_TASKS_SUSPEND_ALL (owner, 2026-08-16): a repo Actions variable
189	  // every Claudinite workflow checks as its FIRST act — when true, the run
190	  // exits cleanly and fires nothing, so the train parks at most one hop after
191	  // suspension. Gates workflow STARTS only: in-flight runs and agent sessions
192	  // finish on their own, and items freeze in place with no labels touched.
193	  let suspendedAll = false;
194	  const crashNextOf = new Set(); // taskIds whose next execution dies mid-claim
195	  const crashDuringWorkOf = new Map(); // taskId -> minutes into the work step the runner dies
196	  const crashAgentOf = new Set(); // taskIds whose next agent session dies mid-run
197	
198	  const schedule = (t, fn) => queue.push({ t, seq: seq++, fn });
199	  const record = (kind, extra) => log.push({ t: now, at: iso(now), kind, ...extra });
200	
201	  const open = () => issues.filter((i) => i.state === 'open');
202	  const has = (i, l) => i.labels.has(l);
203	  // Standing vs ad-hoc is STRUCTURAL (DESIGN §3, owner 2026-08-19 — no origin
204	  // marker): an item bearing a task's bare unqualified title, where that task
205	  // has a frequency at HEAD, IS the task's standing item. An item of a manual
206	  // task, or any item carrying a qualifier, is ad-hoc — outside the family by
207	  // its very title, so invisible to occurrence accounting with nothing
208	  // hand-classified.
209	  const family = (taskId) => issues.filter((i) => i.title === titleOf(taskId));
210	  const isStanding = (i) => {
211	    const task = registry.get(i.taskId);
212	    return !!task && task.frequency !== 'manual' && i.title === titleOf(i.taskId);
213	  };
214	  const standingItem = (taskId) => family(taskId).find((i) => i.state === 'open');
215	
216	  // A park is TWO labels, because that is what the engine writes (DESIGN §4):
217	  // `needs-human` is the state every rule filters on, the sub-label is what the
218	  // human is being asked for. Modeling only the first would make the sim agree
219	  // with the rule's INTENT while diverging from the artifact — exactly the blind
220	  // spot that hid the episode-boundary livelock (F24).
221	  const TRIAGE = ['action', 'decision', 'approval', 'failure'];
222	  const triageLabel = (kind) => `task:needs-human-${TRIAGE.includes(kind) ? kind : 'failure'}`;
223	  const park = (it, from, kind) => {
224	    if (from) it.labels.delete(from);
225	    it.labels.add('needs-human');
226	    it.labels.add(triageLabel(kind));
227	  };
228	  // The road back (DESIGN §4) clears BOTH labels — a re-queue that stripped only
229	  // the state would leave a live item still wearing a triage sub-label, which is
230	  // a shape no rule defines.
231	  const unpark = (it) => {
232	    it.labels.delete('needs-human');
233	    for (const k of TRIAGE) it.labels.delete(triageLabel(k));
234	  };
235	
236	  // Only a fault park holds the task's lane. A park wearing NO sub-label blocks
237	  // too — every item an engine older than the split left behind, which is the
238	  // direction that must be safe.
239	  const blockingPark = (i) =>
240	    has(i, 'needs-human')
241	    && !has(i, 'task:needs-human-action')
242	    && !has(i, 'task:needs-human-decision')
243	    && !has(i, 'task:needs-human-approval');
244	
245	  function createIssue({ taskId, labels, notBefore = null, blockedBy = [], urgent = false, qualifier = null, request = null, model = null }) {
246	    const it = {
247	      request, model,
248	      number: issues.length + 900,
249	      title: titleOf(taskId) + (qualifier ? ` ${qualifier}` : ''),
250	      taskId,
251	      labels: new Set(labels.concat(urgent ? ['task:urgent'] : [])),
252	      state: 'open',
253	      createdAt: now, closedAt: null,
254	      readySince: labels.includes('task:ready') ? now : null,
255	      lastActivity: now,
256	      notBefore, blockedBy,
257	      outcome: null, rolls: [], comments: [], escalated: false,
258	      sessions: [], quarantined: false,
259	    };
260	    issues.push(it);
261	    record('create', { task: taskId, issue: it.number });
262	    return it;
263	  }
264	
265	  function swap(it, from, to) {
266	    it.labels.delete(from);
267	    it.labels.add(to);
268	    it.readySince = to === 'task:ready' ? now : null;
269	    it.lastActivity = now;
270	  }
271	
272	  // F18/F24: the episode boundary is an ARTIFACT on the item, not a property of
273	  // the label transition. Modelling it as "every transition into ready opens a
274	  // new episode" is what made this simulator unable to reproduce F24: it encoded
275	  // the rule's intent, so the paths that end an episode without writing anything
276	  // looked correct here and livelocked in production. So the epoch advances
277	  // exactly where the engine leaves a mark — the scheduler run's reclaim, the F15 revert,
278	  // and the departing executor's strike on a roll or a park (DESIGN §6.2).
279	  //
280	  // A human re-queue deliberately does NOT advance it: a human editing labels
281	  // writes no comment, which is precisely why the strike has to have happened
282	  // already.
283	  function endEpisode(it) { it.claimEpoch = seq++; }
284	
285	  function close(it, outcome) {
286	    it.state = 'closed';
287	    it.closedAt = now;
288	    it.outcome = outcome;
289	    for (const l of [...it.labels]) if (l.startsWith('task:')) it.labels.delete(l);
290	    record('close', { task: it.taskId, issue: it.number, outcome });
291	    // F1, reopened 2026-08-15: whoever closes an item — executor or agent —
292	    // also re-checks blocked items' readiness in code (Blocked-by all closed,
293	    // Not-before passed) and a drain follows, so chain links proceed in
294	    // minutes instead of waiting out the scheduler run. The scheduler run's readiness job stays
295	    // the backstop; a HAND close runs no engine code and is covered by it.
296	    for (const b of open().filter((i) => has(i, 'task:blocked'))) {
297	      const blockersDone = b.blockedBy.every(
298	        (n) => issues.find((x) => x.number === n)?.state === 'closed'
299	      );
300	      if (blockersDone && (b.notBefore === null || now >= b.notBefore)) {
301	        swap(b, 'task:blocked', 'task:ready');
302	        record('ready', { task: b.taskId, issue: b.number, by: 'close' });
303	      }
304	    }
305	    if (pickable().length > 0) {
306	      schedule(now + 1 * MIN, () => executorRun('E1', 'close-drain'));
307	    }
308	  }
309	
310	  // ---- the scheduler run (DESIGN §5): pure function of the clock and the issue list --
311	  function schedulerRun() {
312	    if (suspendedAll) { record('suspended-skip', { workflow: 'scheduler-run' }); return; }
313	    record('scheduler-run', {});
314	    // job 1: instantiate — calendar-only, no preconditions, no signals
315	    for (const task of registry.values()) {
316	      if (task.frequency === 'manual') continue;
317	      const A = mostRecentAnchor(task.frequency, now);
318	      const fam = family(task.id);
319	      // F16 self-heal: if a stale issue list ever let a duplicate standing
320	      // item through (nothing guarantees a REST list from another node sees a
321	      // creation seconds old), close every open one but the oldest. The scheduler run
322	      // is serialized (concurrency group), so this cannot race itself.
323	      // A park that is somebody's inbox rather than a fault is neither the
324	      // standing item nor a duplicate of one, so it leaves both tests and the
325	      // schedule goes on around it (#1032: conflating them parked Shepherd's
326	      // fleet-digest for two days behind one permission gap). It stays in `fam`
327	      // for the occurrence guard below — it DID consume its own occurrence.
328	      const openFam = fam.filter((i) => i.state === 'open')
329	        .filter((i) => !has(i, 'needs-human') || blockingPark(i))
330	        .sort((a, b) => a.number - b.number);
331	      for (const dup of openFam.slice(1)) {
332	        close(dup, 'obsolete');
333	        record('dedupe', { task: task.id, issue: dup.number });
334	      }
335	      if (openFam.length > 0) continue; // standing item exists
336	      // occurrence guard, both halves (F13): an item CREATED at-or-after A
337	      // covers this occurrence — and so does an item CLOSED at-or-after A,
338	      // because a rolled item created in an earlier period that ran today
339	      // consumed today's occurrence. Creation-time alone double-executes.
340	      if (fam.some((i) => i.createdAt >= A || (i.closedAt ?? -Infinity) >= A)) continue;
341	      const firstEver = fam.length === 0;
342	      const blockedByUp =
343	        afterMode === 'blocked-by'
344	          ? (task.after ?? []).map((up) => standingItem(up)?.number).filter(Boolean)
345	          : [];
346	      const born = firstEver || blockedByUp.length > 0 ? 'task:blocked' : 'task:ready';
347	      createIssue({
348	        taskId: task.id,
349	        labels: [born],
350	        notBefore: firstEver ? nextAnchor(task.frequency, now) : null,
351	        blockedBy: blockedByUp,
352	      });
353	    }
354	    // job 2: ready whatever is due
355	    for (const it of open().filter((i) => has(i, 'task:blocked'))) {
356	      const blockersDone = it.blockedBy.every(
357	        (n) => issues.find((x) => x.number === n)?.state === 'closed'
358	      );
359	      if (blockersDone && (it.notBefore === null || now >= it.notBefore)) {
360	        swap(it, 'task:blocked', 'task:ready');
361	        record('ready', { task: it.taskId, issue: it.number });
362	      }
363	    }
364	    // job 4: ADOPT a marked issue (DESIGN §16.3) — label mechanics like the other
365	    // three: no precondition, no signal, no judgment about WHO marked it (that is
366	    // the precondition's, at pickup). The mark is CONSUMED here — the request
367	    // label becomes the queued one — so the gate clears by being acted on and a
368	    // second scheduler run finds nothing to adopt. Re-requesting is re-applying the label.
369	    for (const req of requests.filter((r) => r.state === 'open' && r.labels.has(REQUEST_LABEL))) {
370	      // One issue, one live item (F28). While a prior item is LIVE the mark
371	      // waits on the issue, unconsumed — a later scheduler run takes it. A prior item
372	      // that PARKED is superseded by the re-ask: closed here, so the retry
373	      // never leaves its predecessor parked forever beside the run replacing it.
374	      const prior = issues.filter((i) => i.state === 'open' && i.request === req.number);
375	      if (prior.some((i) => !has(i, 'needs-human'))) continue;
376	      for (const p of prior) {
377	        unpark(p);
378	        p.comments.push({ t: now, body: `superseded: #${req.number} was re-marked` });
379	        close(p, 'obsolete');
380	        record('supersede', { task: p.taskId, issue: p.number, request: req.number });
381	      }
382	      const it = createIssue({
383	        taskId: REQUEST_TASK,
384	        labels: ['task:ready'], qualifier: `#${req.number}`,
385	        request: req.number, model: modelFor(req.labels),
386	      });
387	      req.labels.delete(REQUEST_LABEL);
388	      // The model labels are consumed with the mark (F29): each ask names its
389	      // model afresh, so a label left by an earlier ask never outranks a new one.
390	      for (const l of [...req.labels]) if (l.startsWith(MODEL_LABEL_PREFIX)) req.labels.delete(l);
391	      req.labels.add(QUEUED_LABEL);
392	      record('adopt', { task: REQUEST_TASK, issue: it.number, request: req.number, model: it.model });
393	    }
394	    // job 3: reclaim dead executor claims
395	    for (const it of open().filter((i) => has(i, 'task:executing'))) {
396	      if (now - it.lastActivity >= executingLeashMs) {
397	        swap(it, 'task:executing', 'task:ready');
398	        it.comments.push({ t: now, body: 'reclaimed: executor went silent past the leash' });
399	        endEpisode(it);
400	        record('reclaim', { task: it.taskId, issue: it.number });
401	      }
402	    }
403	  }
404	
405	  // The two write-backs onto the request issue (DESIGN §16.5). Whoever converges
406	  // the item owns the write-back for the end it converged: the executor for a
407	  // declined request, the session for a run that left a PR. A run that FAILED
408	  // writes nothing and leaves the queued label standing — re-arming work that
409	  // writes code is a person's decision, and that standing label is also what stops
410	  // the scheduler run adopting the same request a second time.
411	  function declineRequest(it, why) {
412	    const req = requestOf(it.request);
413	    if (!req) return;
414	    req.labels.delete(QUEUED_LABEL);
415	    req.comments.push({ login: 'claudinite', body: `Not implementing this: ${why}` });
416	    record('request-declined', { issue: req.number, item: it.number, why });
417	  }
418	  function reviewRequest(it) {
419	    const req = requestOf(it.request);
420	    if (!req) return;
421	    req.labels.delete(QUEUED_LABEL);
422	    req.labels.add(IN_REVIEW_LABEL);
423	    record('request-in-review', { issue: req.number, item: it.number });
424	  }
425	
426	  // ---- the executor (DESIGN §6) ---------------------------------------------
427	  function pickable() {
428	    const ready = open().filter((i) => has(i, 'task:ready'));
429	    const live = (taskId) => {
430	      const s = standingItem(taskId);
431	      return s && ['task:ready', 'task:executing', 'task:agent'].some((l) => has(s, l));
432	    };
433	    return ready
434	      .filter((i) => !i.quarantined) // an item no live executor can reach (S18)
435	      .filter((i) => {
436	        // same-title mutex: one task, one execution at a time
437	        if (open().some((o) => o !== i && o.title === i.title &&
438	              (has(o, 'task:executing') || has(o, 'task:agent')))) return false;
439	        // the `after` yield: skip while the upstream's standing item is live
440	        // this cycle (a rolled or needs-human upstream does not block — S23)
441	        if (afterMode === 'yield' && isStanding(i)) {
442	          const ups = registry.get(i.taskId)?.after ?? [];
443	          if (ups.some((up) => live(up))) return false;
444	        }
445	        return true;
446	      })
447	      .map((i) => ({ i, r: prng() }))
448	      // urgent first, then RANDOM among the ready (owner, 2026-08-15) — two
