458	  // The claim is the verified lease (DESIGN §6.2): swap, post a claim
459	  // comment, re-read — earliest comment wins, the loser reverts nothing and
460	  // moves on. `preRead` is the label state the executor saw when it read the
461	  // item; a racing executor's stale read is modeled by passing the snapshot
462	  // taken before the rival's swap landed.
463	  function claim(it, execId, preRead) {
464	    if (!preRead.has('task:ready') || preRead.has('needs-human') ||
465	        preRead.has('task:executing') || preRead.has('task:agent')) return false;
466	    it.labels.delete('task:ready');
467	    it.labels.add('task:executing');
468	    it.readySince = null;
469	    it.lastActivity = now;
470	    it.comments.push({ t: now, seq: seq++, kind: 'claim', exec: execId });
