495	    if (world._apiRefusedUntil != null && now < world._apiRefusedUntil) {
496	      record('handoff-refused', { task: it.taskId, issue: it.number });
497	      park(it, 'task:agent', 'action'); // a token, a URL or a routine is wrong
498	      return;
499	    }
