501	      const { started } = world._apiUnanswered;
502	      world._apiUnanswered = null;
503	      record('handoff-unanswered', { task: it.taskId, issue: it.number, started });
504	      it.comments.push({ t: now, body: 'invocation got no answer — outcome unknown, the agent leash decides' });
505	      if (!started) return; // silent item; the janitor's agent leash is the recovery
506	      const s = { id: `s-${++sessionSeq}`, item: it.number };
507	      it.sessions.push(s);
508	      schedule(now + 30_000, () => startAgentSession(s, it, task));
509	      return;
510	    }
511	    record('handoff', { task: it.taskId, issue: it.number });
512	    const s = { id: `s-${++sessionSeq}`, item: it.number };
513	    it.sessions.push(s);
514	    schedule(now + 30_000, () => startAgentSession(s, it, task));
