517	  function startAgentSession(s, it, task) {
518	    if (it.state !== 'open' || !has(it, 'task:agent')) return;
519	    // No agent-side claim (DESIGN §7, amended 2026-08-15): the session checks,
520	    // not claims — the item wears task:agent and the fire's nonce matches the
521	    // newest hand-off, both modeled by the guard above.
522	    it.lastActivity = now;
523	    if (crashAgentOf.delete(it.taskId)) {
524	      record('agent-died', { task: it.taskId, issue: it.number, session: s.id });
525	      return; // never converges; the janitor's agent leash is the recovery (S11)
526	    }
527	    schedule(now + task.agentMinutes * MIN, () => {
528	      if (it.state !== 'open') return;
529	      if (task.agentFails?.(world, now)) {
530	        park(it, 'task:agent', 'failure');
531	        record('agent-failed', { task: it.taskId, issue: it.number });
532	        return;
533	      }
