535	      // deliberately left an unmerged PR is in the same position as a worker that
536	      // did — succeeded, not finished, waiting on a named reviewer. Modeled here
537	      // because the request task is the first agentic task whose every successful
538	      // run ends that way.
539	      if (task.deliversOpenPr?.(world, now)) {
540	        if (it.request != null) reviewRequest(it);
