601	    // the item executing" but "is my claim still the newest" — a reclaim-then-
602	    // re-pick puts a newer claim on the item, and the stale runner must see
603	    // it and abandon silently rather than hand off work it no longer owns.
604	    const myClaim = it.comments.filter((c) => c.kind === 'claim').at(-1);
605	    const mineStill = () => it.state === 'open' && has(it, 'task:executing') &&
