614	    // the work legally runs — and the item's timeline shows live progress
615	    // instead of going dark for the duration.
616	    if (!heartbeatsDisabled) {
617	      for (let m = heartbeatMinutes; m * MIN < workMs; m += heartbeatMinutes) {
618	        if (diesAtMin !== null && m >= diesAtMin) break;
619	        schedule(now + m * MIN, () => {
620	          if (!mineStill()) return;
