624	      }
625	    }
626	    if (diesAtMin !== null) {
627	      // the runner dies mid-work: heartbeats stop, the completion never runs,
628	      // and the leash reclaims from the LAST heartbeat — recovery is bounded
629	      // by the leash, not by the work's duration
630	      schedule(now + diesAtMin * MIN, () => {
631	        record('executor-crash', { task: it.taskId, issue: it.number });
