635	      });
636	      return; // the run dies with the runner — no settle, no ordinary re-dispatch
637	    }
638	    schedule(now + workMs, () => {
639	      if (!mineStill()) return; // reclaimed while (presumed) dead: the run is gone
640	      it.lastActivity = now;
641	      if (task.codeWorkFails?.(world, now)) {
642	        endEpisode(it);                       // F24: a park strikes its claim
