672	  // F15: the pick filters (same-title mutex, `after` yield) are read from
673	  // possibly-stale state, so two executors can pass them simultaneously and
674	  // claim DIFFERENT items that the filters should have serialized — a twin
675	  // pair, or an upstream and its dependent. The lease protects one item, not
676	  // one title. So after WINNING a claim, re-verify the filters against live
677	  // state: if a conflicting item now holds an EARLIER claim (comment order —
678	  // the same arbiter the lease trusts), revert this claim to task:ready and
679	  // move on. Bounded (one revert), deterministic (comment order), and the
680	  // earlier claim never even notices.
681	  function postClaimVerify(it, execId) {
682	    const myClaim = it.comments.filter((c) => c.kind === 'claim').at(-1);
683	    const conflicts = open().filter((o) => {
684	      if (o === it) return false;
685	      const live = has(o, 'task:executing') || has(o, 'task:agent');
686	      if (!live) return false;
687	      if (o.title === it.title) return true; // twin
688	      if (afterMode === 'yield' && isStanding(it)) {
689	        const ups = registry.get(it.taskId)?.after ?? [];
690	        if (ups.some((up) => o.title === titleOf(up) && isStanding(o))) return true;
691	      }
692	      return false;
693	    });
694	    const earlier = conflicts.some((o) =>
695	      o.comments.filter((c) => c.kind === 'claim').at(-1)?.seq < myClaim.seq);
696	    if (!earlier) return true;
697	    endEpisode(it);
698	    swap(it, 'task:executing', 'task:ready');
699	    record('claim-reverted', { task: it.taskId, issue: it.number, exec: execId });
700	    return false;
701	  }
