703	  // One executor RUN — a workflow run in the real deployment — performs ONE
704	  // item. Not a configured maximum: the essence of the executor (owner,
705	  // 2026-08-15). The run claims an item, sees it through to its settle (roll,
706	  // close, hand-off, failure), and ends; if the queue still has pickable
707	  // items it RE-DISPATCHES a fresh run (`workflow_dispatch`, which the
708	  // default GITHUB_TOKEN may fire), so the queue drains run by run and a
709	  // run's timeout sizes to a single work bound. Every run records its
710	  // trigger — scheduler-run-drain | label-event | close-drain | re-dispatch |
711	  // failure-redispatch — so tests assert WHAT caused each run, not just that
712	  // items converged.
713	  let runSeq = 0;
714	  function executorRun(execId = 'E1', trigger = 'label-event') {
715	    if (suspendedAll) { record('suspended-skip', { workflow: 'executor', trigger }); return; }
716	    const runId = `R${++runSeq}`;
717	    record('executor-run', { run: runId, exec: execId, trigger });
718	    const settle = () => {
719	      record('run-end', { run: runId, exec: execId, trigger, settled: 1 });
720	      if (pickable().length > 0) {
721	        schedule(now + 1 * MIN, () => executorRun(execId, 're-dispatch'));
722	      }
723	    };
724	    const step = () => { // claim attempts until one item is held, or the queue is empty
725	      const it = pickable()[0];
726	      if (!it) { record('run-end', { run: runId, exec: execId, trigger, settled: 0 }); return; }
727	      if (!claim(it, execId, new Set(it.labels))) return step(); // loser tries another item
