1	// SCENARIOS.md, executable. Each test is a timed play-through against the
2	// simulator in sim.mjs: "at time X, Y happens", then run the virtual clock and
3	// assert on the issue store and the event log. Scenario numbers match the
4	// prose document (§H's standing-item replay + the stable earlier scenarios);
5	// a test here going red means the DESIGN.md mechanism, as modeled, breaks.
6	//
7	// The cast mirrors SCENARIOS.md's "Cast and constants" table. Preconditions
8	// read `world`, the scenario-owned signal state — task questions only, never
9	// calendar ones (DESIGN §6.4).
10	
11	import test from 'node:test';
12	import assert from 'node:assert/strict';
13	import { makeSim, T } from './sim.mjs';
14	
15	function cast() {
16	  return [
17	    {
18	      id: 'basics/baselining', frequency: 'daily-2h', outcome: 'done',
19	      codeWorkMinutes: 21, agentMinutes: 30,
20	      precondition: (w) => ({ run: !!w.mountBehind, reason: 'mount converged, no pending notes' }),
21	      requestsAgent: (w) => !!w.baseliningNeedsJudgment,
22	      codeWorkFails: (w) => !!w.mountBroken,
23	    },
24	    {
25	      id: 'grow/growth-extract', frequency: 'daily-1h', after: ['basics/baselining'],
26	      outcome: 'done', codeWorkMinutes: 2, agentMinutes: 35,
27	      precondition: (w) => ({ run: !!w.extractHasLessons, reason: 'nothing new to extract' }),
28	    },
29	    {
30	      id: 'grow/growth-promote', frequency: 'daily', after: ['grow/growth-extract'],
31	      outcome: 'done', codeWorkMinutes: 1, agentMinutes: 2,
32	      precondition: (w) => ({ run: !!w.promoteHasCandidates, reason: 'nothing staged' }),
33	    },
34	    {
35	      id: 'tidy/tidy-issues', frequency: 'daily', outcome: 'done',
36	      codeWorkMinutes: 1, agentMinutes: 16,
37	      precondition: (w, now) => ({
38	        run: w.issueTouchedAt != null && now - w.issueTouchedAt <= 24 * 3600e3,
39	        reason: 'no issue touched in window',
40	      }),
41	    },
42	    {
43	      id: 'chrome/store-release', frequency: 'daily', outcome: 'done', codeWorkMinutes: 3,
44	      precondition: (w) => ({ run: !!w.releasePending, reason: 'nothing to release' }),
45	    },
46	    {
47	      id: 'gcec/create-extractor', frequency: 'hourly', outcome: 'done',
48	      codeWorkMinutes: 4, agentMinutes: 10,
49	      precondition: (w) => ({ run: !!w.pendingRequest, reason: 'no eligible requests' }),
50	    },
51	    {
52	      id: 'tidy/tidy-prs', frequency: 'weekly', outcome: 'done',
53	      codeWorkMinutes: 1, agentMinutes: 5,
54	      precondition: (w) => ({ run: !!w.stalePrs, reason: 'no stale PRs' }),
55	    },
56	    { id: 'sheepdog/fleet-baseline', frequency: 'manual', outcome: 'done', codeWorkMinutes: 1, agentMinutes: 5 },
57	  ];
58	}
59	
60	// The triage-split cast (S41–S43), kept OUT of `cast()` on purpose: these two
61	// always-run tasks would add executor contention to every other scenario, and
62	// S15's mutex timing is sensitive to exactly that.
63	const SEEDS = {
64	  id: 'sheepdog/fleet-seeds', frequency: 'daily', outcome: 'done', codeWorkMinutes: 2,
65	  precondition: () => ({ run: true }),
66	  codeWorkFails: (w) => !!w.patScopeMissing,
67	  codeWorkTriage: () => 'action', // the PAT lacks Contents: write — a person grants it
68	};
69	const REGENERATE = {
70	  id: 'site/regenerate', frequency: 'daily', outcome: 'done', codeWorkMinutes: 2,
71	  precondition: () => ({ run: true }),
72	  deliversOpenPr: () => true,
73	};
74	
75	const evals = (sim, task) => sim.log.filter((e) => e.kind === 'evaluate' && e.task === task);
76	const closedOf = (sim, task) =>
77	  sim.family(task).filter((i) => !i.seeded && i.state === 'closed' && i.outcome != null);
78	
79	// ---- S1' — quiet night: one evaluation per task per period, then everything
80	// sleeps as a blocked standing item wearing its next wake time.
81	test("S1' quiet night: one ask per period, items roll and sleep", () => {
82	  const sim = makeSim({ tasks: cast() })
83	    .seedSteadyState('2026-08-12T00:00Z')
84	    .run('2026-08-12T00:00Z', '2026-08-13T00:00Z');
85	
86	  for (const task of ['basics/baselining', 'tidy/tidy-issues', 'chrome/store-release']) {
87	    assert.equal(evals(sim, task).length, 1, `${task} asked once`);
88	    const it = sim.standingItem(task);
89	    assert.ok(it.labels.has('task:blocked'), `${task} sleeps`);
90	    assert.ok(it.notBefore > T('2026-08-12T23:59Z'), `${task} wakes tomorrow`);
91	    assert.equal(it.rolls.length, 1);
92	  }
93	  // the hourly task asks hourly — that is its declared cadence, not a defect
94	  assert.equal(evals(sim, 'gcec/create-extractor').length, 23);
95	  // manual tasks never instantiate
96	  assert.equal(sim.family('sheepdog/fleet-baseline').length, 0);
97	  // nothing ran, nothing escalated, nothing closed
98	  assert.equal(sim.log.filter((e) => e.kind === 'handoff' || e.kind === 'escalate').length, 0);
99	});
100	
101	// ---- S2 — happy path: work exists, the item runs to a closed outcome.
102	test('S2 happy path: touched issues -> item runs, closes done', () => {
103	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
104	  sim.at('2026-08-12T04:02Z', ({ world }) => { world.issueTouchedAt = T('2026-08-12T04:02Z'); });
105	  sim.run('2026-08-12T00:00Z', '2026-08-12T12:00Z');
106	
107	  const [done] = closedOf(sim, 'tidy/tidy-issues');
108	  assert.ok(done, 'tidy-issues converged');
109	  assert.equal(done.outcome, 'done');
110	  // claimed at the 04:17 drain, agent 16m: closed ~04:34
111	  assert.ok(done.closedAt <= T('2026-08-12T04:40Z'));
112	  assert.equal(evals(sim, 'tidy/tidy-issues').length, 1);
113	});
114	
115	// ---- S3' — work appears mid-window: nothing wakes until the next anchor;
116	// the ask happens once per period, and tomorrow's ask finds the work.
117	test("S3' mid-window work waits for the next anchor, then runs", () => {
118	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
119	  sim.at('2026-08-12T09:03Z', ({ world }) => { world.issueTouchedAt = T('2026-08-12T09:03Z'); });
120	  sim.run('2026-08-12T00:00Z', '2026-08-13T12:00Z');
121	
122	  const asks = evals(sim, 'tidy/tidy-issues');
123	  assert.equal(asks.length, 2, 'one ask per day, two days');
124	  assert.ok(asks[0].t < T('2026-08-12T05:00Z') && asks[0].run === false, 'day 1: declined');
125	  assert.ok(asks[1].t > T('2026-08-13T04:00Z') && asks[1].run === true, 'day 2: found the work');
126	  assert.equal(closedOf(sim, 'tidy/tidy-issues').length, 1);
127	});
128	
129	// ---- S4 — the late-fire night: all cron fires drop, one late scheduler run at 05:41,
130	// and the chain still runs the same morning, in order, via the pick-time yield.
131	test('S4 late fire: the chain completes the same morning, ordered', () => {
132	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
133	  sim.at('2026-08-12T00:01Z', ({ world }) => {
134	    world.mountBehind = true;         // baselining has real work (no judgment needed)
135	    world.extractHasLessons = true;   // and so does the rest of the chain
136	    world.promoteHasCandidates = true;
137	  });
138	  sim.dropSchedulerRuns('2026-08-12T00:00Z', '2026-08-12T05:41Z');
139	  sim.schedulerRunAt('2026-08-12T05:41Z');
140	  sim.run('2026-08-12T00:00Z', '2026-08-12T09:00Z');
141	
142	  const [base] = closedOf(sim, 'basics/baselining');
143	  const [extract] = closedOf(sim, 'grow/growth-extract');
144	  const [promote] = closedOf(sim, 'grow/growth-promote');
145	  assert.ok(base && extract && promote, 'all three converged');
146	  assert.ok(base.closedAt < extract.closedAt, 'baselining before extract');
147	  assert.ok(extract.closedAt < promote.closedAt, 'extract before promote');
148	  assert.ok(promote.closedAt < T('2026-08-12T09:00Z'), 'same morning, not tomorrow');
149	  // extract was never picked while baselining was live
150	  const baseClaim = sim.log.find((e) => e.kind === 'evaluate' && e.task === 'basics/baselining');
151	  const extractClaim = sim.log.find((e) => e.kind === 'evaluate' && e.task === 'grow/growth-extract');
152	  assert.ok(extractClaim.t >= base.closedAt, 'yield held while upstream ran');
153	  assert.ok(baseClaim.t >= T('2026-08-12T05:41Z'), 'nothing happened before the late scheduler run');
154	  // F1 (reopened 2026-08-15): the close-time drain picks the yielded dependent
155	  // in minutes — chain links no longer wait out the scheduler run
156	  assert.ok(extractClaim.t <= base.closedAt + 5 * 60e3, 'picked within minutes of the upstream closing');
157	});
158	
159	// ---- S5 — the scheduler run is down for three days: rolled items simply wake on the
160	// first scheduler run back; exactly one catch-up ask per task, no backfill.
161	test('S5 three-day outage: one catch-up ask, no backfill', () => {
162	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-11T00:00Z');
163	  sim.dropSchedulerRuns('2026-08-11T09:00Z', '2026-08-14T10:00Z');
164	  sim.run('2026-08-11T00:00Z', '2026-08-14T23:00Z');
165	
166	  const asks = evals(sim, 'tidy/tidy-issues');
167	  assert.equal(asks.length, 2, 'Tuesday once, Friday once — Wed/Thu gone, not backfilled');
168	  assert.ok(asks[1].t >= T('2026-08-14T10:17Z'), 'catch-up on the first scheduler run back');
169	  const it = sim.standingItem('tidy/tidy-issues');
170	  assert.equal(sim.family('tidy/tidy-issues').filter((i) => i.state === 'open').length, 1,
171	    'still exactly one standing item');
172	  assert.ok(it.notBefore > T('2026-08-14T23:00Z') - 24 * 3600e3, 'rolled to the next real anchor');
173	});
174	
175	// ---- S13' — an ad-hoc item's no-go closes it (no anchor to roll to).
176	// Ad-hoc is STRUCTURAL (DESIGN §3): a qualifier is what makes this item ad-hoc —
177	// an unqualified item of a scheduled task would BE the standing item, and roll.
178	test("S13' ad-hoc no-go closes obsolete instead of rolling", () => {
179	  const sim = makeSim({ tasks: cast() }).seedSteadyState('2026-08-12T00:00Z');
180	  let adhoc;
181	  sim.at('2026-08-12T10:00Z', (s) => { adhoc = s.createItem('tidy/tidy-issues', { urgent: true, qualifier: 'one-off' }); });
182	  sim.run('2026-08-12T05:00Z', '2026-08-12T12:00Z'); // start past the 04:17 scheduler run: scheduled item exists rolled
183	
184	  assert.equal(adhoc.state, 'closed');
185	  assert.equal(adhoc.outcome, 'obsolete');
186	  assert.equal(adhoc.rolls.length, 0, 'ad-hoc items never roll');
187	  // …and the standing item is untouched by the ad-hoc twin: still one, still rolled.
188	  assert.equal(sim.family('tidy/tidy-issues').filter((i) => i.state === 'open').length, 1);
189	});
190	
191	// ---- S14'/S16' — forcing is waking the standing item; a force that finds no
192	// work rolls again with the reason on record, a force that finds work runs.
